mapper.select:
SELECT DISTINCT dbi.id AS deviceId, dbi.device_code AS deviceCode, dbi.device_name AS deviceName, dbi.device_type_name AS deviceTypeName, dbi.device_sub_type_name AS deviceSubTypeName, dbi.workshop_id AS workshopId, dbi.workshop_name AS workshopName, COUNT(ah.id) AS alarmCount, MAX(ah.start_ts) AS latestAlarmStartTs FROM biz_device_mgmt.alarm_history ah INNER JOIN biz_device_base.device_base_info dbi ON ah.device_id = dbi.id WHERE ah.tenant_id = #{tenantId} AND ah.is_active = true AND dbi.factory_id = #{factoryId}
AND dbi.workshop_id = #{workshopId}
GROUP BY dbi.id, dbi.device_code, dbi.device_name, dbi.device_type_name, dbi.device_sub_type_name, dbi.workshop_id, dbi.workshop_name ORDER BY latestAlarmStartTs DESC

SELECT DISTINCT dbi.id AS deviceId, dbi.device_code AS deviceCode, dbi.device_name AS deviceName, dbi.device_type_name AS deviceTypeName, dbi.device_sub_type_name AS deviceSubTypeName, dbi.workshop_id AS workshopId, dbi.workshop_name AS workshopName, COUNT(ah.id) AS alarmCount, MAX(ah.start_ts) AS latestAlarmStartTs FROM biz_device_mgmt.alarm_history ah INNER JOIN biz_device_base.device_base_info dbi ON ah.device_id = dbi.id WHERE ah.tenant_id = #{tenantId} AND ah.is_active = true AND dbi.factory_id = #{factoryId}
AND dbi.workshop_id = #{workshopId}
GROUP BY dbi.id, dbi.device_code, dbi.device_name, dbi.device_type_name, dbi.device_sub_type_name, dbi.workshop_id, dbi.workshop_name ORDER BY latestAlarmStartTs DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(DISTINCT dbi.id)
FROM biz_device_mgmt.alarm_history ah
INNER JOIN biz_device_base.device_base_info dbi ON ah.device_id = dbi.id
WHERE ah.tenant_id = #{tenantId}
  AND ah.is_active = true
  AND dbi.factory_id = #{factoryId}

      AND dbi.workshop_id = #{workshopId}
